/* Install controls remain visible even when the browser offers no automatic prompt. */
(()=>{let deferred=null,sessionInstalled=false,registrationState='Comprobando el modo sin conexión…';const isStandalone=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true||sessionInstalled;const isApple=()=>/iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);const inApp=()=>/FBAN|FBAV|Instagram|TikTok|WhatsApp|; wv\)/i.test(navigator.userAgent);const text=()=>isStandalone()?'✓ App instalada':deferred?'Instalar aplicación':'Instalar / ver instrucciones';function update(){document.querySelectorAll('[data-pwa-install]').forEach(b=>b.textContent=text());const status=document.getElementById('pwaRegistration');if(status)status.textContent=registrationState;const native=document.getElementById('pwaNative');if(native)native.hidden=!deferred||isStandalone()}
function ensureDialog(){let dialog=document.getElementById('pwaHelp');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='pwaHelp';dialog.setAttribute('aria-labelledby','pwaTitle');dialog.style.cssText='border:1px solid #cbd7cd;border-radius:24px;padding:26px;max-width:580px;width:calc(100% - 32px);max-height:85vh;overflow:auto;color:#214e48;background:#faf8f2;font:18px system-ui;line-height:1.6';dialog.innerHTML='<h2 id="pwaTitle">Instalar MeComunico</h2><p>Se instala desde el navegador como PWA. No necesitas descargar un APK ni buscarla en una tienda.</p><p id="pwaDevice"></p><ol><li><strong>Android:</strong> abre el enlace directamente en Chrome → menú ⋮ → Instalar aplicación o Añadir a pantalla principal. Confirma la instalación cuando Chrome la ofrezca.</li><li><strong>iPhone o iPad:</strong> abre en Safari → Compartir → Añadir a pantalla de inicio → activa Abrir como app web si aparece → Añadir.</li><li><strong>Computadora:</strong> usa Chrome o Edge y busca el icono de instalación en la barra de direcciones o la opción correspondiente del menú.</li></ol><p>Si lo abriste dentro de WhatsApp, Facebook o TikTok, usa el menú para abrirlo en Chrome o Safari.</p><p id="pwaRegistration" style="font-size:15px" aria-live="polite"></p><p>Después de instalar, abre MeComunico desde su icono. La disponibilidad de voces sin internet depende del dispositivo. Si el navegador no ofrece instalación, puedes seguir usando la web.</p><button id="pwaNative" style="margin:6px" hidden>Instalar ahora</button><button id="pwaClose" style="margin:6px">Cerrar</button>';document.body.appendChild(dialog);dialog.querySelector('#pwaClose').onclick=()=>dialog.close();dialog.querySelector('#pwaNative').onclick=()=>promptInstall();return dialog}
function showHelp(){const d=ensureDialog();document.getElementById('pwaDevice').textContent=isStandalone()?'MeComunico está abierto en modo aplicación.':inApp()?'Estás en un navegador integrado: abre este enlace en Chrome o Safari.':isApple()?'En tu iPhone o iPad la instalación se hace desde el menú Compartir de Safari.':deferred?'El navegador ya ofrece la instalación. Puedes pulsar Instalar ahora.':'El navegador todavía no ofrece instalación automática. Puedes usar su menú; el botón no puede forzar esa decisión.';update();if(!d.open)d.showModal()}
async function promptInstall(){if(!deferred){showHelp();return}const event=deferred;deferred=null;update();try{await event.prompt();const result=await event.userChoice;if(result?.outcome==='accepted'){registrationState='Solicitud aceptada. Comprueba el icono en tu dispositivo.'}else registrationState='Instalación cancelada. Puedes intentarlo desde el menú del navegador.'}catch{registrationState='No se pudo abrir el instalador. Usa las instrucciones del navegador.'}update()}
window.installMeComunico=()=>{if(deferred&&!isStandalone())promptInstall();else showHelp()};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;update()});window.addEventListener('appinstalled',()=>{sessionInstalled=true;deferred=null;update()});document.addEventListener('click',e=>{if(e.target.closest('[data-pwa-install]')){e.preventDefault();window.installMeComunico()}});window.addEventListener('DOMContentLoaded',()=>{update();if(!window.isSecureContext){registrationState='Se necesita HTTPS para instalar y activar el modo sin conexión.';update();return}if(!('serviceWorker'in navigator)){registrationState='Este navegador no ofrece service workers. La web sigue disponible.';update();return}navigator.serviceWorker.register('./sw.js').then(async registration=>{registrationState='Preparando los archivos para uso sin conexión…';update();try{await registration.update()}catch{}navigator.serviceWorker.ready.then(()=>{registrationState='Modo sin conexión registrado. Abre la app una vez con internet y pruébala después sin conexión.';update()});const worker=registration.installing;if(worker)worker.addEventListener('statechange',()=>{if(worker.state==='redundant'){registrationState='No se pudo actualizar el modo sin conexión. Revisa internet o vuelve a abrir el sitio.';update()}})}).catch(()=>{registrationState='No se pudo registrar el modo sin conexión. Prueba con conexión en Chrome o Safari y revisa HTTPS.';update()})});})();
